import React, { useState } from 'react';
import styled from '@emotion/styled';
import { DashboardLayout, DashContent, DashSection, DashPanel, theme } from '@atlantis/shared';
import type { NavEntry } from '@atlantis/shared';
import { CITIES } from './cities';
import type { City } from './cities';
import { useCityData } from './hooks';
import CitySelector from './components/CitySelector';
import CityOverview from './components/CityOverview';
import WeatherTimeline from './components/WeatherTimeline';
import AirQualityChart from './components/AirQualityChart';
import CityCompare from './components/CityCompare';

const SECTIONS: NavEntry[] = [
  {
    id: 'dashboard',
    name: 'Dashboard',
    icon: 'layout-grid',
    children: [
      { id: 'overview', name: 'City Overview', icon: 'map-pin' },
      { id: 'weather', name: 'Weather Timeline', icon: 'thermometer' },
      { id: 'air-quality', name: 'Air Quality', icon: 'wind' },
      { id: 'compare', name: 'Compare Cities', icon: 'bar-chart-2' },
    ],
  },
];

const SectionTitle = styled.h2`
  font-size: ${theme.typography.fontSizeLg};
  font-weight: 700;
  color: ${theme.colors.mainText};
  margin-bottom: ${theme.spacing.md};
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: ${theme.spacing.sm};
`;

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [city, setCity] = useState<City>(CITIES[0]);
  const { snapshot, weather, airQuality, loading, error, retry } = useCityData(city);

  return (
    <DashboardLayout title="CityPulse" sections={SECTIONS} topBarRight={topBarRight}>
      <DashContent>
        <DashSection id="overview">
          <SectionTitle>
            City Overview
            <CitySelector value={city.id} onChange={setCity} />
          </SectionTitle>
          {error ? (
            <div style={{ padding: '24px', color: '#8b949e', fontSize: 14, display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 12 }}>
              Weather data unavailable — the API may be temporarily down.
              <button onClick={retry} style={{ padding: '6px 16px', cursor: 'pointer', background: 'none', border: '1px solid #30363d', borderRadius: 6, color: '#e6edf3', fontFamily: 'inherit', fontSize: 13 }}>
                Retry
              </button>
            </div>
          ) : (
            <CityOverview snapshot={snapshot} loading={loading} />
          )}
        </DashSection>

        <DashSection id="weather">
          <DashPanel>
            <WeatherTimeline weather={weather} loading={loading} />
          </DashPanel>
        </DashSection>

        <DashSection id="air-quality">
          <DashPanel>
            <AirQualityChart airQuality={airQuality} loading={loading} />
          </DashPanel>
        </DashSection>

        <DashSection id="compare">
          <DashPanel>
            <CityCompare />
          </DashPanel>
        </DashSection>
      </DashContent>
    </DashboardLayout>
  );
}
